from pathlib import Path
import json, urllib.request
three={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V','MSE':'M','UNK':'X'}
seqs={}
for p in sorted(Path('input_targets').glob('target*.pdb')):
    chains={}; seen=set()
    for line in p.open():
        if line.startswith('ATOM'):
            ch=line[21].strip() or '_'; resn=line[17:20].strip(); resseq=line[22:26].strip()+line[26].strip()
            key=(ch,resseq,resn)
            if key not in seen:
                seen.add(key); chains.setdefault(ch,[]).append(three.get(resn,'X'))
    seqs[p.stem]={ch: ''.join(vals) for ch,vals in chains.items()}
Path('experiments/target_id/sequences.json').write_text(json.dumps(seqs,indent=2)+"\n")

def rcsb_search(seq, ident=0.98):
    query={
      "query": {"type":"terminal","service":"sequence","parameters":{"evalue_cutoff":1,"identity_cutoff":ident,"sequence_type":"protein","value":seq}},
      "request_options":{"scoring_strategy":"sequence","paginate":{"start":0,"rows":20}},
      "return_type":"polymer_entity"
    }
    data=json.dumps(query).encode()
    req=urllib.request.Request('https://search.rcsb.org/rcsbsearch/v2/query', data=data, headers={'Content-Type':'application/json'})
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.load(resp)
summary={}
for t,cs in seqs.items():
    seq=next(iter(cs.values()))
    hits=[]
    for ident in [0.99,0.95,0.9,0.8,0.6,0.4]:
        try:
            res=rcsb_search(seq, ident)
            hits=res.get('result_set',[])
        except Exception as e:
            print(t,'RCSB error',ident,repr(e))
            continue
        if hits:
            break
    summary[t]={"identity_cutoff":ident,"total_count":len(hits),"top":[{"identifier":h.get('identifier'),"score":h.get('score')} for h in hits[:10]]}
Path('experiments/target_id/rcsb_sequence_hits.json').write_text(json.dumps(summary,indent=2)+"\n")
for t,s in summary.items():
    print(t, 'identity>=',s['identity_cutoff'],'hits',s['total_count'],'top',s['top'][:5])
